#include "Rover.h"

// A variable: int means a whole number, steps is its name, 1 is its value.
// It's made out here so it keeps its value every time loop() runs.
int steps = 1;

void setup() {
  Serial.begin(9600);  // turns on the Serial Monitor
}

void loop() {
  Serial.println(steps);  // shows what steps is right now
  forward(steps);
  turnRight();
  forward(1);
  turnLeft();
}

